"""Reconstruct paper diagnostics from retained intermediates generated by release.py.

This path does not train warning models, replay CGM, or refit clinical models.
"""
import argparse
import json
from pathlib import Path
import subprocess
import sys

sys.path.insert(0, str(Path(__file__).resolve().parent))
from release import PACKAGE, sha, load, contained, separate, environment, verify, check_environment


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--data-root', type=Path, required=True, help='Completed source reproduction tree')
    parser.add_argument('--raw-root', type=Path, required=True, help='Read-only original TN10 metadata/counts directory')
    parser.add_argument('--output-root', type=Path, required=True)
    args = parser.parse_args()
    verify(); versions = check_environment()
    data, raw = args.data_root.resolve(), args.raw_root.resolve()
    out = separate(args.output_root, data, raw)
    dependency = load(PACKAGE / 'provenance/external_dependencies.json')
    before, identities, paths = {}, {}, {}
    for relative, entry in dependency['inputs'].items():
        path = contained(raw, Path(relative).name) if relative.startswith('card002/raw/') else contained(data, relative)
        paths[relative] = path
        before[relative] = sha(path)
        if relative.startswith('card002/raw/') and before[relative] != entry['sha256']:
            raise ValueError('Original TN10 input identity changed: '+relative)
        identities[relative] = dict(sha256=before[relative], bytes=path.stat().st_size,
                                   original_run_byte_match=before[relative] == entry['sha256'])
    out.mkdir(parents=True)
    env = environment(out)
    commands = [
        ('endpoints', [sys.executable, '-B', str(PACKAGE/'src/paper_endpoint_decomposition.py'),
                       '--data-root', str(data), '--output-root', str(out/'endpoints')]),
        ('tn10', [sys.executable, '-B', str(PACKAGE/'src/paper_tn10_diagnostics.py'),
                  '--data-root', str(data), '--raw-root', str(raw),
                  '--output-root', str(out/'tn10'), '--stage', 'run'])]
    for name, command in commands:
        with (out/(name+'.log')).open('w', encoding='utf-8') as stream:
            subprocess.run(command, cwd=PACKAGE, env=env, stdout=stream, stderr=subprocess.STDOUT, check=True)
    comparisons = {}
    for relative, expected in load(PACKAGE/'provenance/reconstruction_expected.json')['exact_output_sha256'].items():
        actual = sha(contained(out, relative))
        if actual != expected:
            raise ValueError('Diagnostic differs from authoritative bytes: ' + relative)
        comparisons[relative] = actual
    if before != {name: sha(path) for name,path in paths.items()}:
        raise ValueError('An input changed during reconstruction')
    result = dict(status='PASS', scope='Retained-intermediate reconstruction; no model training or clinical refitting',
                  inputs=identities, input_hashes_unchanged=True, exact_outputs=comparisons,
                  commands=[c for _,c in commands], environment=versions,
                  identity_note='Original-run hash differences are reported. Fresh source runs change provenance fields; the seven committed scientific diagnostics must remain byte-identical.')
    (out/'reconstruction_result.json').write_text(json.dumps(result, indent=2)+'\n', encoding='utf-8')
    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    main()
